sql.where:
la.deleted_yn = 'N'
AND la.management_no ILIKE CONCAT('%', #{criteria.managementNo}, '%')
AND personnel.name ILIKE CONCAT('%', #{criteria.teacherName}, '%')
AND la.management_item_code = #{criteria.managementItemCode}
AND la.certification_status = #{criteria.certificationStatus}
AND la.teacher_user_id = #{criteria.viewerUserId}

    AND EXISTS (
        SELECT 1 FROM organization_user_mappings scope_mapping
        WHERE scope_mapping.user_id = #{criteria.viewerUserId}
          AND scope_mapping.organization_code = la.organization_code
          AND scope_mapping.status = 'ACTIVE'
    )
